<template><view class="page"><view class="page-head"><text class="eyebrow">NEW CHECK-IN</text><view class="page-title">发布签到</view><text class="muted">创建任务后，参与者即可在活动空间完成签到。</text></view><view class="card form-card"><view class="field"><text class="field-label">任务标题</text><input v-model="title" class="input" placeholder="例如：景区入口集合" /></view><view class="field"><text class="field-label">任务说明（选填）</text><textarea v-model="description" class="textarea" placeholder="补充签到要求或集合说明" /></view><button class="primary-btn" @click="submit">发布签到</button></view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{api}from'@/services/api';const id=ref(0),title=ref(''),description=ref('');onLoad((o:any)=>id.value=Number(o.id));async function submit(){if(!title.value.trim())return uni.showToast({title:'请输入标题',icon:'none'});await api(`/activities/${id.value}/sign-tasks`,'POST',{title:title.value,description:description.value});uni.showToast({title:'发布成功'});setTimeout(()=>uni.navigateBack(),500)}</script><style scoped>.gap{margin-top:20rpx}</style>
